// JAH demo program — runnable with: node demo.js
// Record JAH-APX7-000011 — Worked example: locating 'quinoa blight' across scales
// Lineage trace: walks a derivation graph from an output back to its root sources.
'use strict';
var edges = [["taxonomy-entry", "scientific-name"], ["scientific-name", "agronomy-term"], ["agronomy-term", "street-term"], ["scientific-name", "paper-definition"]];
var target = "taxonomy-entry";
var parents = {};
edges.forEach(function (e2) { (parents[e2[0]] = parents[e2[0]] || []).push(e2[1]); });
var chain = [target]; var cur = target; var guard = 0;
while (parents[cur] && parents[cur].length && guard++ < 50) { cur = parents[cur][0]; chain.push(cur); }
console.log('target=' + target + ' lineage_depth=' + (chain.length - 1));
console.log('chain: ' + chain.join(' <- '));
var roots = chain.filter(function (x) { return !parents[x]; });
console.log('root_sources=' + roots.join(', '));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX7-000012 — Failure modes: false friends and drift
// Uncertainty quantification: separates measured spread from model uncertainty.
'use strict';
var ms = [0.88, 0.91, 0.62, 0.89, 0.9, 0.87];
var modelVar = 0.006;
var mean = ms.reduce(function (a, b) { return a + b; }, 0) / ms.length;
var mvar = ms.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / ms.length;
var total = mvar + modelVar;
console.log('n=' + ms.length + ' mean=' + mean.toFixed(3));
console.log('measured_variance=' + mvar.toFixed(4) + ' (' + (100 * mvar / total).toFixed(1) + '%)');
console.log('model_variance=' + modelVar.toFixed(4) + ' (' + (100 * modelVar / total).toFixed(1) + '%)');
console.log('total_uncertainty_stddev=' + Math.sqrt(total).toFixed(4));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX7-000013 — Scaling: planetary terminology coverage
// Monte Carlo workload simulation: latency distribution under a synthetic load model.
'use strict';
var n = 2000, seed = 71;
var a = seed >>> 0;
function rnd() { a = (Math.imul(a, 1664525) + 1013904223) >>> 0; return a / 4294967296; }
var sum = 0, sum2 = 0;
for (var i = 0; i < n; i++) { var x = 20 + rnd() * 380; sum += x; sum2 += x * x; }
var mean = sum / n, variance = sum2 / n - mean * mean;
console.log('samples=' + n + ' mean_ms=' + mean.toFixed(2) + ' stddev_ms=' + Math.sqrt(variance).toFixed(2));

